from engine import *
topics=[
I('tutorial','Самоучител: някой показва стъпките',P('Отваряш програма за рисунки и искаш да изрежеш изображение. Виждаш много бутони, но още не знаеш кой е нужен. <strong>Самоучител</strong> е ръководство, което те води през последователност от действия до определен резултат. Среща се и английското име <strong>tutorial</strong>.','Самоучителят може да е текст с картинки, книга или видео. Често предлага упражнения и проверки. Добър е този, който обяснява откъде започваме, какво правим и как трябва да изглежда резултатът. Версията на програмата също има значение: при друга версия бутонът може да е преместен.','В учебника задачата е да се намери самоучител за Photoshop. В готовия ни пример търсенето е насочено към официалните уроци на Adobe и темата „изрязване на изображение“. Вместо да преглеждаме всички функции, избираме урок за точно тази задача.')+E('Резултатът в примера: от снимката е премахнат излишният край, а важният обект е останал. Самоучителят е помогнал да изпълним цялата малка задача.'),[('Цел','Да изрежем излишния край на снимка'),('Самоучител','Поредица от действия с обяснен резултат'),('Проверка','Важният обект остава в изображението')],C('Кои признаци са полезни при избор на самоучител?',['Обяснява конкретна задача.','Показва последователни действия и резултат.','Версията на програмата няма никакво значение.','Може да съдържа текст, картинки или видео.','Подходящ е за знанията на начинаещия.','Добър е само ако изброява всички бутони без примери.'],[0,1,3,4],'Полезният самоучител води към резултат и е подходящ за задачата, версията и знанията на ученика. Самият списък с бутони не обяснява как да се използват.')),
I('help','Помощна система: намираме отговор за конкретна функция',P('След като вече използваш програма, може да се запиташ какво означава една команда. <strong>Помощната система</strong>, означена често като <strong>Help</strong> или „Помощ“, съдържа справочни обяснения за функциите и работата с приложението.','Например самоучителят те води от снимка до готова картичка. Помощната система обяснява какво прави командата за изрязване или как се избира място за запис. Двата източника се допълват. Помощта също може да съдържа примери и цели уроци.','Достъпът може да е от меню Помощ, бутон с въпросителен знак или клавиш F1, когато приложението го поддържа. Някои системи са вградени, други отварят уеб страница и изискват интернет. Не всяка програма предлага един и същ вид помощ.')+E('Готов пример: за да разберем „Извличане“ в архиватор, отваряме Помощ и търсим темата за извличане. За да научим целия процес на работа с архиви отначало, избираме последователен самоучител.'),[('„Какво прави тази команда?“','Търсим справка в помощната система'),('„Как да направя цял проект?“','Търсим последователен самоучител'),('Help / Помощ','Може да е в програмата или онлайн')],C('Кои твърдения за помощната система са верни?',['Обяснява функции и команди.','Винаги представлява хартиена книга.','Може да се отваря от меню Помощ.','При онлайн помощ може да е необходим интернет.','Може да се използва заедно със самоучител.','Всяко приложение задължително има еднакъв бутон и еднакъв прозорец за помощ.'],[0,2,3,4],'Помощта предоставя справочна информация и се предлага в различни форми. Менютата и начините за отваряне зависят от приложението.')),
I('bandizip-help','Намираме подходящата тема в помощта на Bandizip',P('В примера от учебника е използвано менюто <strong>Помощ → Отиди до помощната страница</strong>. Отваря се онлайн справочник на английски. Не е нужно да знаеш всяка дума: първо свържи заглавието с въпроса, на който търсиш отговор.','Учебникът посочва четири групи. <strong>License & Registration</strong> е за лиценз и регистрация. <strong>Exclusive features of Bandizip Paid Edition</strong> описва допълнителни функции на платено издание. <strong>Features & Technical Terms</strong> обяснява функции и термини. <strong>Troubleshooting</strong> помага при неизправности.','Заглавията и подредбата могат да се променят с изданието, но начинът на избор остава полезен. Питаме се дали търсим условие за използване, описание на функция или решение на проблем.')+T(['Въпрос в готовия пример','Къде търсим?'],[['Как се извличат файлове?','Функции и технически термини / тема за извличане.'],['Защо архивът не се отваря?','Troubleshooting — проблеми и решения.'],['Кои функции са в платеното издание?','Разделът за платеното издание.']]),[('License & Registration','Лиценз и регистрация'),('Features & Technical Terms','Функции и понятия'),('Troubleshooting','Отстраняване на неизправности')],C('Кои насочвания са правилни?',['За проблем търсим Troubleshooting.','За лиценз търсим License & Registration.','За извличане търсим обяснения на съответната функция.','За всяка команда непременно купуваме платено издание.','Разделът за платеното издание описва неговите допълнителни възможности.','Избираме тема само по мястото ѝ в списъка, без да четем заглавието.'],[0,1,2,4],'Заглавието на раздела ни насочва според въпроса. Търсенето на помощ не означава автоматично необходимост от платена версия.')),
I('office-help','Помощта за текст и електронни таблици',P('OpenOffice е пакет с няколко приложения. Затова първо уточняваме дали работим с текст, таблица или презентация. Една дума като „форматиране“ има различни конкретни действия според задачата.','В примера е отворено <strong>Помощ → Помощ за OpenOffice</strong>. В помощния прозорец се избира приложение и тема. В показания в учебника изглед вляво се намират темите, а вдясно — обяснението на избраната тема.','За текстово заглавие търсим форматиране на знаци: шрифт, размер и получер. За клетка в електронна таблица търсим формат на клетка — например число, дата или процент. Първо прочитаме указанията, после ги прилагаме към подходящия обект.')+E('Готов пример: в текстов документ заглавието „Моят град“ е маркирано и форматирано получер с размер 18. В таблица стойността 0,25 е показана като 25% чрез процентен формат. Едно и също общо действие „форматиране“ е довело до различно представяне според вида на обекта.'),[('Текстово заглавие','Получер, размер 18'),('Клетка със стойност 0,25','Процентен формат → 25%'),('Избор на тема','Според приложението и обекта')],C('Кои изводи следват от примерите?',['Избираме помощ според приложението.','За текст може да търсим форматиране на знаци.','За процент в клетка може да търсим формат на клетка.','Помощта за всяка програма винаги описва единствено печат.','Прочитаме и после прилагаме указанията върху правилния обект.','Размер 18 на шрифта означава 18% в електронната таблица.'],[0,1,2,4],'Текстът и клетките имат различни настройки. Изборът на точната тема прави помощта полезна за конкретната задача.')),
I('comparison','Сравняваме помощ и търсим информация за RAR',P('В учебника се предлага да се разгледа и помощта на IZArc. Полезното сравнение е <strong>как се достига до темите</strong>, дали има съдържание или търсене и къде се отварят обясненията. Не е нужно двата архиватора да изглеждат еднакво.','В готов пример помощта на единия архиватор е уеб страница, а на другия — отделен прозорец с теми. Това описва конкретните показани издания, а не правило за всички бъдещи версии.','Друга задача е да разберем как се отваря RAR файл. RAR е архивен формат. В помощта на Bandizip се търси тема за отваряне и извличане. Програмата може да поддържа извличане от формат, без да поддържа създаването на архив в същия формат.')+E('Показан резултат: отворен е album.rar, прегледан е списъкът със снимки и чрез Извличане е избрана папка Album. Отварянето на архива показва съдържанието; извличането поставя файловете в избраната папка.'),[('Сравнение на помощ','Уеб страница или прозорец; теми и търсене'),('album.rar','Архив със снимки'),('Извличане → Album','Снимките са в избраната папка')],C('Кои твърдения са верни?',['Помощните системи могат да имат различен интерфейс.','RAR е вид архивен формат.','Отварянето на архива и извличането на файловете имат различен резултат.','Поддръжката на извличане винаги доказва поддръжка на създаване на същия формат.','При търсене избираме думи за конкретната задача.','Всички версии на IZArc и Bandizip имат напълно еднаква помощ.'],[0,1,2,4],'Сравняваме начина за достигане до информацията, а не очакваме еднакъв интерфейс. Четенето на архивен формат не гарантира създаването му.')),
I('video','Готов пример: учим обработка на видео и звук',P('Учебникът предлага да се намери самоучител за обработка на видео и звук и да се направи кратък клип. Тук използваме готова ситуация, за да проследим ученето без телефон и без инсталиране.','Даден е учебен клип с продължителност <strong>12 секунди</strong>. Първите 2 секунди са излишни. Избраният самоучител обяснява изрязване на начало, регулиране на звук и запазване на готовия резултат. Първо е направено копие на оригинала.','След изрязването клипът е 10 секунди. Звукът е намален до удобна сила. Готовият файл е записан с различно име и е прегледан отначало докрай. После в примера е качен в споделена учебна папка в OneDrive с подходящ достъп за съучениците.')+E('Самопроверка: оригиналът е запазен; новият клип започва от желаното място; времетраенето е 10 секунди; звукът се чува; споделя се готовият файл. Ако не знаем командата за запис на резултата, търсим съответната тема в помощта.'),[('Оригинал','12 секунди; пазим копие'),('Обработка','Премахнати първи 2 секунди; настроен звук'),('Готов резултат','10 секунди; нов файл; преглед и споделяне')],O('Как самоучителят и помощната система се допълват в примера с клипа?','Обясни в 3–5 изречения със свои думи и използвай изрязването на първите 2 секунди като пример.','Самоучителят показва поредицата от действия за обработката на клипа. По него премахваме първите 2 секунди от 12-секундния оригинал и получаваме 10 секунди. Ако не разбираме конкретна команда, например запазването на готовото видео, търсим обяснението ѝ в помощната система. Проверяваме новия файл и пазим оригинала. За самопроверка: различи цялата последователност от справката за конкретна функция; включи пример, а не само определения.'))]

build(12,'help-and-tutorials','Използване на помощни системи и самоучители при работа с приложни програми','37–38',P('Нова програма не се научава чрез налучкване на всички бутони. Можем да използваме обяснения, които ни водят към резултат, и справки, които отговарят на конкретен въпрос.','Ще различаваш самоучител от помощна система и ще проследиш примери с изображения, архиви, текст, таблици и видео. Всички нужни данни са дадени тук; не е необходим телефон, нова инсталация или личен облачен профил.'),topics,['<strong>Самоучителят води през поредица от действия към резултат.</strong>','<strong>Помощната система обяснява функции и команди.</strong> Тя може да е вградена или онлайн.','<strong>Търсим по конкретна задача и подходяща версия.</strong>','<strong>Избираме тема според приложението и обекта.</strong> Текст и клетка имат различни настройки.','<strong>Проверяваме готовия резултат и пазим оригинала.</strong>'],['Стр.37: самоучител и задача Photoshop; помощ/Help; цялото разграничение на четирите раздела в Bandizip.','Стр.38: помощ на OpenOffice, видео/звук/прехвърляне/обработка/OneDrive като завършен пример без телефон.','Заключителните задачи: разлика между помощ и самоучител, форматиране, сравняване с IZArc, RAR и извличане.'],[('Adobe: уроци за Photoshop','https://helpx.adobe.com/photoshop/tutorials.html'),('Bandizip: извличане','https://en.bandisoft.com/bandizip/help/how-to-unzip/'),('OpenOffice: помощ','https://www.openoffice.org/documentation/'),('IZArc','https://www.izarc.org/')], 'Уточнение: не всяка програма непременно има помощна система; формата и езикът ѝ зависят от изданието. Сравнението на уеб помощ и отделен прозорец е условен готов пример. Практическите условия са включени като обяснени резултати, без зависимост от лични файлове и профили.')
